import {sessionViewport} from './viewport.mjs';
import {CHECKPOINTS,MAX_RUN_TIME,steerVelocity,checkpointScore,finishScore,isFinished,clamp} from './engine.mjs';
import {mountGameProgress,recordEvent} from './progression.mjs';
if(typeof mountGameProgress==='function')mountGameProgress('marble-run');
const c=document.querySelector('#run'),ctx=c.getContext('2d'),$=s=>document.querySelector(s);let W=1,H=1,dpr=1,running=false,paused=false,last=0,elapsed=0,score=0,cp=0,input=0,pointer=null,best=Number(localStorage.getItem('shrunk-marble-best')||0);const m={x:0,y:0,vx:0,vy:0,r:12};
let orientationBlocked=innerHeight>=innerWidth;
function resize(){if(orientationBlocked)return;dpr=Math.min(devicePixelRatio||1,2);W=window.visualViewport?.width||innerWidth;H=window.visualViewport?.height||innerHeight;c.width=W*dpr;c.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);if(!running)resetMarble()}addEventListener('resize',resize);resize();
function resetMarble(){m.x=W*.5;m.y=H*.12;m.vx=0;m.vy=80}function sync(){scoreEl.textContent=String(score).padStart(4,'0');bestEl.textContent=best;timeEl.textContent=Math.max(0,MAX_RUN_TIME-elapsed).toFixed(1)}const scoreEl=$('#score'),bestEl=$('#best'),timeEl=$('#time');
function start(){running=true;paused=false;elapsed=0;score=0;cp=0;input=0;resetMarble();$('#start').hidden=true;$('#results').hidden=true;sync()}$('#play').onclick=start;$('#replay').onclick=start;$('#pause').onclick=()=>{if(running){paused=true;$('#pausebox').showModal()}};$('#resume').onclick=()=>{paused=false;$('#pausebox').close()};$('#restart').onclick=()=>{$('#pausebox').close();start()};
function pnt(e){const r=c.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}c.addEventListener('pointerdown',e=>{if(!running||paused||orientationBlocked)return;pointer={id:e.pointerId,start:pnt(e).x};c.setPointerCapture?.(e.pointerId)});c.addEventListener('pointermove',e=>{if(!pointer||pointer.id!==e.pointerId)return;input=clamp((pnt(e).x-pointer.start)/65,-1,1)});function up(e){if(pointer?.id===e.pointerId){pointer=null;input=0}}c.addEventListener('pointerup',up);c.addEventListener('pointercancel',up);
function end(){running=false;score+=finishScore(elapsed,cp);recordEvent('marble_run_complete',{score,time:elapsed,checkpoints:cp},'marble-run');if(score>best){best=score;localStorage.setItem('shrunk-marble-best',best);$('#bestline').textContent='NEW PERSONAL BEST'}else $('#bestline').textContent='PERSONAL BEST '+best;$('#final').textContent=String(score).padStart(4,'0');sync();$('#results').hidden=false}
function collideCircle(x,y,r){const dx=m.x-x,dy=m.y-y,d=Math.hypot(dx,dy);if(d<r+m.r){const nx=dx/(d||1),ny=dy/(d||1),dot=m.vx*nx+m.vy*ny;if(dot<0){m.x=x+nx*(r+m.r);m.y=y+ny*(r+m.r);m.vx=(m.vx-1.8*dot*nx)*.78;m.vy=(m.vy-1.8*dot*ny)*.78}}}
function collideBar(cx,cy,w,h,a,bounce=.74){const ca=Math.cos(a),sa=Math.sin(a),dx=m.x-cx,dy=m.y-cy;let lx=dx*ca+dy*sa,ly=-dx*sa+dy*ca;const hx=w/2,hy=h/2,qx=clamp(lx,-hx,hx),qy=clamp(ly,-hy,hy);let nx=lx-qx,ny=ly-qy,d=Math.hypot(nx,ny);if(d>=m.r)return;if(d<.001){const px=hx-Math.abs(lx),py=hy-Math.abs(ly);if(px<py){nx=lx<0?-1:1;ny=0;d=0;lx=(lx<0?-hx:hx)+nx*m.r}else{nx=0;ny=ly<0?-1:1;d=0;ly=(ly<0?-hy:hy)+ny*m.r}}else{nx/=d;ny/=d;const push=m.r-d;lx+=nx*push;ly+=ny*push}const wx=nx*ca-ny*sa,wy=nx*sa+ny*ca;m.x=cx+lx*ca-ly*sa;m.y=cy+lx*sa+ly*ca;const dot=m.vx*wx+m.vy*wy;if(dot<0){m.vx=(m.vx-(1+bounce)*dot*wx)*.88;m.vy=(m.vy-(1+bounce)*dot*wy)*.88}}
function update(dt){if(!running||paused||orientationBlocked)return;elapsed+=dt;if(elapsed>=MAX_RUN_TIME){end();return}m.vx=steerVelocity(m.vx,input,dt);m.vy+=125*dt;m.x+=m.vx*dt;m.y+=m.vy*dt;const L=W*.17,R=W*.83;if(m.x-m.r<L){m.x=L+m.r;m.vx=Math.abs(m.vx)*.7}if(m.x+m.r>R){m.x=R-m.r;m.vx=-Math.abs(m.vx)*.7}collideCircle(W*.34,H*.35,24);collideCircle(W*.67,H*.48,28);collideCircle(W*.43,H*.67,22);collideBar(W*.61,H*.26,W*.19,12,.18);collideBar(W*.72,H*.60,W*.15,18,-.28);collideBar(W*.28,H*.54,W*.14,10,.34,.82);collideBar(W*.56,H*.69,W*.12,16,-.42,.82);collideBar(W*.65,H*.77,W*.24,10,-.16,.8);collideBar(W*.37,H*.43,W*.12,9,-.38,.86);collideBar(W*.73,H*.84,W*.13,12,.32,.84);const gateX=W*(.5+.12*Math.sin(elapsed*1.45));collideBar(gateX,H*.58,W*.13,9,0,.9);collideCircle(W*.76,H*.72,16);for(let i=cp;i<CHECKPOINTS.length;i++){if(m.y>=H*CHECKPOINTS[i]){score+=checkpointScore(i,Math.hypot(m.vx,m.vy));cp=i+1;sync()}else break}if(isFinished(m.y,H)){end();return}if(m.y>H+40||m.x<0||m.x>W){score=Math.max(0,score-75);resetMarble()}sync()}
function draw(){ctx.clearRect(0,0,W,H);const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#856b4c');g.addColorStop(1,'#4c3a2a');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.fillStyle='#30291f';ctx.fillRect(0,0,W*.15,H);ctx.fillRect(W*.85,0,W*.15,H);ctx.strokeStyle='#c4fb7144';ctx.setLineDash([6,10]);ctx.beginPath();ctx.moveTo(W*.5,H*.1);ctx.lineTo(W*.5,H*.92);ctx.stroke();ctx.setLineDash([]);CHECKPOINTS.forEach((q,i)=>{ctx.fillStyle=i<cp?'#c4fb7144':'#ffffff15';ctx.fillRect(W*.17,H*q-2,W*.66,4)});function prop(x,y,r,label){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle='#ded8c9';ctx.fill();ctx.strokeStyle='#777';ctx.lineWidth=5;ctx.stroke();ctx.fillStyle='#222';ctx.font='bold 9px Arial';ctx.textAlign='center';ctx.fillText(label,x,y+3)}prop(W*.34,H*.35,24,'TAPE');prop(W*.67,H*.48,28,'CUP');prop(W*.43,H*.67,22,'CAP');function bar(cx,cy,w,h,a,color,label){ctx.save();ctx.translate(cx,cy);ctx.rotate(a);ctx.fillStyle=color;ctx.fillRect(-w/2,-h/2,w,h);ctx.fillStyle='#222';ctx.font='bold 8px Arial';ctx.textAlign='center';if(label)ctx.fillText(label,0,3);ctx.restore()}bar(W*.61,H*.26,W*.19,12,.18,'#d8b07a','RULER');bar(W*.72,H*.60,W*.15,18,-.28,'#d88989','ERASER');bar(W*.28,H*.54,W*.14,10,.34,'#d8b07a','BANK');bar(W*.56,H*.69,W*.12,16,-.42,'#d88989','BLOCK');bar(W*.65,H*.77,W*.24,10,-.16,'#e4c859','PENCIL');bar(W*.37,H*.43,W*.12,9,-.38,'#c8c4bc','CARD');bar(W*.73,H*.84,W*.13,12,.32,'#d88989','ERASER');const gateX=W*(.5+.12*Math.sin(elapsed*1.45));bar(gateX,H*.58,W*.13,9,0,'#c4fb71','MOVING GATE');prop(W*.76,H*.72,16,'CAP');ctx.fillStyle='#c4fb71';ctx.fillRect(W*.17,H*.91,W*.66,5);ctx.fillStyle='#111';ctx.font='900 11px Arial';ctx.fillText('FINISH',W*.5,H*.9);const rg=ctx.createRadialGradient(m.x-4,m.y-5,2,m.x,m.y,m.r);rg.addColorStop(0,'#fff');rg.addColorStop(.35,'#a8e8ff');rg.addColorStop(1,'#18465c');ctx.beginPath();ctx.arc(m.x,m.y,m.r,0,Math.PI*2);ctx.fillStyle=rg;ctx.fill();ctx.strokeStyle='#c4fb71';ctx.lineWidth=2;ctx.stroke()}
function frame(t){const dt=Math.min((t-last)/1000||0,.033);last=t;update(dt);draw();requestAnimationFrame(frame)}sync();requestAnimationFrame(frame);

let orientationSince=0;sessionViewport(v=>{const was=orientationBlocked;orientationBlocked=v.blocked;if(v.blocked){const id=pointer?.id;pointer=null;input=0;if(id!==undefined&&c.hasPointerCapture(id))c.releasePointerCapture(id);if(!orientationSince)orientationSince=performance.now();}else{orientationSince=0;const shell=document.querySelector('main');shell.style.cssText=`position:fixed;left:${v.left}px;top:${v.top}px;width:${v.width}px;height:${v.height}px`;resize();last=performance.now();}});
